def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
sources={p.relative_to(ROOT).as_posix():sha(p) for folder in ('src','web','data') for p in (ROOT/folder).rglob('*') if p.is_file() and '__pycache__' not in p.parts and p.suffix not in ('.pyc','.pyo')}
preserved={p.relative_to(ROOT).as_posix():sha(p) for folder in ('examples','evaluations','outputs','archives') for p in (ROOT/folder).rglob('*') if p.is_file() and not p.is_relative_to(OUT) and '__pycache__' not in p.parts and p.suffix not in ('.pyc','.pyo')}
for p in ROOT.glob('*.zip'):preserved[p.name]=sha(p)
baseline=dict(frozen_at=datetime.now(timezone.utc).isoformat(),cases_sha256=sha(OUT/'cases.json'),source_sha256=sources,preserved_sha256=preserved,git_base=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),version_note='Uncommitted v3 workspace, app code/data frozen for campaign',planned=50,provider='codex',execution='UI form only; four local identical server instances; no Mock and no injected faults',scope='Synthetic product facts and realistic work briefs, not real customer data or production benchmarks')
(OUT/'baseline.json').write_text(json.dumps(baseline,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(OUT/'测试清单.md').write_text('# 50组真实模型网页实验：冻结清单\n\n需求在首条运行前冻结，不包含预设结果。所有必填字段完整，全部选择真实模型。V50是预先安排的V01重复需求。素材是虚构产品资料，工作情境是现实化设计。\n\n'+'\n\n'.join(f"## {c['id']} {c['name']}\n\n背景：{c['context']}\n\n需求：{c['request']['topic']}\n\n受众：{c['request']['audience']}；平台：{c['request']['platform']}；时长：{c['request']['target_seconds']}秒（{c['request']['duration_mode']}）；风格：{c['request']['style']}" for c in cases)+'\n',encoding='utf-8')
(OUT/'rubric.md').write_text('# 预先确定的评阅口径\n\n先看原始需求，再看实际输出与Trace，不能按completed判断成功。分别记录：事实依据及引用、完整覆盖与排他范围、画面/受众/风格可用性、估算时长与真实性限制、改稿是否针对反馈、缺资料或工具问题是否如实说明。实际结果后再评分，不改原需求，不为通过而重写案例。\n\n每次保留输入、输出、Trace、材料快照、模型元数据、网页输入与输出、截图。模型启动失败与模型作出的业务停止分开统计；若没有实际模型响应，不计入50次真实模型实验，原失败仍保留并另建重试目录。复算只是记录一致性，不是离线替代实验或语义正确性证明。\n\n无人工造故障；四个独立本地实例并行，耗时不作为单用户性能基准。开发助手进行逐稿复核，非独立盲评；50组有限样本不代表生产成功率。\n',encoding='utf-8')
print(json.dumps({'out':str(OUT),'cases':len(cases),'source_files':len(sources),'preserved_files':len(preserved),'cases_sha256':baseline['cases_sha256']},ensure_ascii=False))
